R=json.load(open('final_fit_results.json'));B=json.load(open('robust_cos_results.json'));G=json.load(open('rbf_final_results.json'));S=json.load(open('fit_start_values.json'))
units='The actual units are not supplied. `U_y`, `U_x1`, and `U_x2` denote placeholders for the unknown units of `y`, `x1`, and `x2`; `s` denotes seconds. Normalized features and exponents are dimensionless. '
reference='General estimation reference: L. Ljung, System Identification: Theory for the User, second edition, Prentice Hall, 1999 (bibliographic details checked against the publisher). '
polyref='Polynomial feature libraries are also used in S. L. Brunton, J. L. Proctor and J. N. Kutz, Discovering governing equations from data by sparse identification of nonlinear dynamical systems, PNAS 113, 3932–3937, 2016, DOI 10.1073/pnas.1517384113 (publisher record checked). This candidate does not use that paper\'s sparse estimator. '
rbfref='Reference: J. Moody and C. J. Darken, Fast Learning in Networks of Locally-Tuned Processing Units, Neural Computation 1, 281–294, 1989, DOI 10.1162/neco.1989.1.2.281 (publisher bibliographic record checked). '
def par(name,value,unit,typ,desc):return dict(name=name,value=float(value),unit=unit,type=typ,description=desc)
def scales():
 return [par('y0',1,'U_y','fixed','State translation `y0 = 1` U_y, chosen before polynomial fitting as a convenient origin close to the observed lower state range; it is not a known physical zero.'),par('s0',1,'U_y','fixed','State scale `s0 = 1` U_y, chosen to make `(y-y0)/s0` dimensionless without changing its numerical value.'),par('u0',60,'U_x1','fixed','Input scale `u0 = 60` U_x1, chosen as a convenient near-central scale from inspection of training input magnitudes, not fitted.'),par('v0',20,'U_x2','fixed','Input scale `v0 = 20` U_x2, chosen as a convenient near-central scale from inspection of training input magnitudes, not fitted.')]
def pterms(powers):
 atoms=['((y-y0)/s0)','(x1/u0)','(x2/v0)'];out=[]
 for p in powers:
  out.append('*'.join(a if int(k)==1 else a+'**'+str(int(k)) for a,k in zip(atoms,p) if k) or '1')
 return out
def numeric_starts(names,values,us):
 return '; '.join('`'+n+' = '+format(float(v),'.17g')+'`'+(' '+u if u!='-' else '') for n,v,u in zip(names,values,us))
data='All rows of `data/train.csv` and `data/val.csv`, treated as two separately initialized uninterrupted trajectories, with sampling period `5` s from TASK.md. No measured-state resets inside either file and no rows removed. Validation was first used for structure comparison, then explicitly included in final calibration to use both available excitation patterns. Final validation errors are calibration diagnostics, not independent generalization estimates. '
criterion='Sum of squared full-rollout state residuals `y_sim-y` over every row after the first in each file. Each rollout uses classical fourth-order Runge–Kutta, one step of `5` s, with `x1` and `x2` held at the left sample. This matches the supplied evaluation objective rather than treating the sampled derivative as an instantaneous derivative. '
commonmethod='Final parameters were estimated jointly with nonlinear least squares using `scipy.optimize.least_squares`, trust-region reflective method, `jac` supplied by forward sensitivity propagation through all four RK4 stages, and `x_scale = "jac"`. This uses the exact chosen rollout and avoids finite-difference Jacobian cost; ordinary least squares cannot minimize its nonlinear trajectory objective. Parameter optimization coordinates are scaled by `Max(Abs(initial_value),0.01)`, a dimensionless numerical conditioning rule implemented in `refine.py`. The stopping tolerances `ftol = 1e-8`, `xtol = 1e-8`, and `gtol = 1e-8` are dimensionless solver settings; the maximum is `120` function evaluations. Final optimization is deterministic and uses no random seed. '
limitations='No physical apparatus, units, measurement noise model or intended operating envelope is known. Inputs and the state are correlated along only two supplied files, so the fitted coefficients need not be separately causally identifiable. One anomalous middle transition occurs in each file; it was not used as a reset. Oscillatory serially correlated derivative residuals remain, consistent with omitted dynamics or timing effects but not proof of their cause; an autonomous scalar state with only the two current inputs cannot explicitly represent input history. Extrapolation beyond the supplied excitation is unvalidated. '
models={}
for label in ['poly3','rational2']:
 r=next(r for r in R if r['label']==label);terms=pterms(r['powers']);names=['c'+str(i) for i in range(len(terms))];P=scales()
 for name,c,term in zip(names,r['coef'],terms):P.append(par(name,c,'U_y/s','fitted','Coefficient multiplying `'+term+'`, jointly estimated by final rollout least squares; initial value came from the training-only fits described in estimation.'))
 num=' + '.join(n+'*'+t for n,t in zip(names,terms))
 if label=='rational2':
  names+=['k'];P.append(par('k',r['coef'][-1],'-','fitted','Nonnegative state-normalization coefficient in `1+k*((y-y0)/s0)**2`, jointly estimated with numerator coefficients.'))
  expr='('+num+')/(1+k*((y-y0)/s0)**2)'
  family='Rational nonlinear state-space vector field: quadratic polynomial numerator and positive quadratic state denominator. Rational model-family context: N. M. Mangan, S. L. Brunton, J. L. Proctor and J. N. Kutz, Inferring Biological Networks by Sparse Identification of Nonlinear Dynamics, IEEE Transactions on Molecular, Biological and Multi-Scale Communications 2, 52–63, 2016, DOI 10.1109/TMBMC.2016.2633265 (publisher bibliographic record checked). This fit is not sparse implicit SINDy. '
  interpret='The numerator terms `'+num+'` give constant drift, state feedback, input forcing and their quadratic interactions. Division by `1+k*((y-y0)/s0)**2` progressively attenuates the whole vector field away from the chosen state origin. `k >= 0` makes the denominator at least `1`, so there are no denominator poles. All terms have mathematical rather than established physical interpretations.'
  origin='The quadratic derivative fit was substantially better than the affine baseline, but full-trajectory errors remained state dependent. A positive state-dependent denominator was therefore a guessed smooth rate attenuation, tested after polynomial and input-dependent damping models. The numerator keeps the full degree-two polynomial library; no term was selected by a physical assumption. The denominator was chosen instead of higher numerator degree as a compact alternative. The nonnegative denominator constraint was retained for domain safety.'
  extra='The bound `k >= 0` is an assumed regularity constraint, not a measured property. The first `10` numerator coefficients were initialized by the degree-two training derivative ordinary least-squares solution, and `k = 0` was the initial rational denominator. Training-only rollout refinement supplied the numeric final-stage start listed below. '
 else:
  expr=num;family='Degree-three polynomial continuous-time nonlinear state-space model, using a complete monomial feature library. '+polyref
  interpret='Each `c` parameter is the coefficient of the normalized monomial specified in its parameter description. `c0` is constant drift; degree-one state and input terms provide affine dynamics; quadratic and cubic state terms curve the restoring field; products couple the state-dependent rate to inputs or couple the two inputs. No particular physical meaning is established for these mathematical effects.'
  origin='Started with an affine baseline, then complete polynomial libraries of degrees `2` through `6` and ridge penalties. Degree-two terms greatly reduced derivative error; degree-three state-input interactions reduced rollout error further. Higher-degree libraries offered limited validation benefit and additional extrapolation risk, so degree `3` was retained. The feature library was a generic regression assumption, not a recovered physical law. Greedy sparse nonlinear feature search by the helper did not outperform this library. All degree-three terms were retained because the complete library was well conditioned after scaling and the chosen structure improved validation rollouts.'
  extra='Initial ordinary least squares on all training `dy` values used `numpy.linalg.lstsq` and needed no starting values. The resulting coefficient vector was then refined jointly against the uninterrupted training rollout with the same RK4 nonlinear least-squares method. That training-only fit supplies the numeric final-stage starts below; no final parameters were tied or independently fixed. '
 starts=numeric_starts(names,r['start'],['U_y/s']*len(terms)+(['-'] if label=='rational2' else []))
 method=commonmethod+extra+'Actual final-stage starts: '+starts+'. These starts were used because the training-only rollout fits had already produced finite plausible trajectories. No random numbers apply. '
 models[label]=dict(expressions={'dy':expr},parameters=P,estimation=dict(criterion=criterion,data=data,method=method,script='reproduce_models.py'),discussion=dict(family=family,interpretation=units+interpret,origin=origin,limitations=limitations+('A polynomial field has no general global RK4 stability guarantee; its state-feedback slope is very slightly positive at a few supplied samples. ' if label=='poly3' else 'Although its denominator is globally positive, bounded-input global trajectory stability is not established. ')))
# Smooth nonlinear relaxation candidate, with explicitly dimensionless signed power.
r=next(r for r in B if r['eps']==.05);names=['b0','b1','d0','d1','h','p','q','r'];us=['U_y/s']*4+['U_y','-','-','-']
P=[par('s0',1,'U_y','fixed','State normalization `s0 = 1` U_y, chosen for dimensionless state power without changing its numerical magnitude.'),par('v0',20,'U_x2','fixed','Input normalization `v0 = 20` U_x2, chosen during initial data inspection, not fitted.'),par('a0',180,'U_x1','fixed','Trigonometric input scale `a0 = 180` U_x1. Chosen as a structural hypothesis so that the cosine crosses zero at `x1 = 90` U_x1, near the supplied upper excitation. This does not assert that the input is an angle or has degree units.'),par('eps',.05,'-','fixed','Dimensionless smoothing scale `eps = 0.05`, chosen after diagnosing steep feedback in the preliminary `eps = 0.001` model. Values `0.02` and `0.05` were compared on both supplied files; the latter reduced steepness without worsening rollout fit. It corresponds to `eps*s0 = 0.05` U_y and avoids a singular fractional-power slope.'),par('floor',1e-12,'-','fixed','Positive guard `floor = 1e-12`, chosen to define fractional input powers and parameter derivatives at zero. Not estimated from data.')]
desc=['Constant drift coefficient','Input forcing amplitude multiplying `Max(x2/v0,floor)**q`','Baseline restoring amplitude','Cosine-dependent restoring amplitude','State translation in the nonlinear response','Dimensionless state power','Dimensionless second-input power','Dimensionless cosine power']
for n,c,u,d in zip(names,r['coef'],us,desc):P.append(par(n,c,u,'fitted',d+'; jointly estimated by final rollout least squares.'))
z='((y-h)/s0)';g=z+'*('+z+'**2+eps**2)**((p-1)/2)';expr='b0+b1*Max(x2/v0,floor)**q-(d0+d1*Max(cos(pi*x1/a0),floor)**r)*'+g
bounds='Bounds are assumed regularity/search constraints: `b1 >= 0`, `0 <= d0 <= 0.03` U_y/s, `0 <= d1 <= 0.1` U_y/s, `0.8 <= h <= 1.05` U_y, `0.4 <= p <= 1`, `0.1 <= q <= 4`, and `0.1 <= r <= 5`. `b0` is unbounded. '
models['cos_power']=dict(expressions={'dy':expr},parameters=P,estimation=dict(criterion=criterion,data=data,method=commonmethod+'An initial trigonometric feature family was fitted against training `dy` by separable nonlinear least squares (variable projection): `scipy.optimize.least_squares` for the translation and powers, with `numpy.linalg.lstsq` profiling linear amplitudes at each iteration. Two starts were used for the original translation, `h = 0.95` U_y and `h = 0.99` U_y; powers started at `p = 0.5`, `q = 1`, and `r = 1`. The smaller derivative sum of squares selected that initialization. Preliminary smoothed derivative and training-rollout fits then provided the final-stage initialization. The final smoothing was chosen explicitly for lower feedback slope and near-identical rollout error, not claimed as a physical parameter. All eight final fitted parameters were then estimated together with `eps = 0.05` held fixed. '+bounds+'Actual final-stage starts: '+numeric_starts(names,r['start'],us)+'. No random seed applies.',script='reproduce_models.py'),discussion=dict(family='Scalar nonlinear relaxation / generalized power-law drift with trigonometric gain scheduling. This is a phenomenological nonlinear state-space ODE, not a known physical apparatus model. '+reference,interpretation=units+'The forcing is `b0+b1*Max(x2/v0,floor)**q`. The normalized state response is `'+g+'`; it is smooth and odd around `y = h` U_y, approximately a signed power far from that translation and approximately linear very near it. The positive factor `d0+d1*Max(cos(pi*x1/a0),floor)**r` supplies input-dependent restoring feedback: the feedback becomes weaker as the input increases over the supplied range. Cosine clipping is a mathematical gain saturation, not evidence for an angular actuator.',origin='Polynomial coefficients suggested input-dependent feedback. Signed/shifted power regression brought the state exponent near a square root; the fitted feedback varied nonlinearly with the first input. Cosine, sine and algebraic input-gain families were therefore guessed and compared by derivative fit and validation rollouts. The cosine family gave a compact competitive alternative. A smooth signed power replaced a clipped fractional power so the state field stays real and differentiable below the fitted translation. Larger smoothing was subsequently tested to reduce fixed-step RK4 stiffness.',limitations=limitations+'The fixed trigonometric scale is not independently identified; nothing establishes periodic behavior beyond the supplied range. At the final parameters, the analytic upper bound on the feedback slope magnitude multiplied by the sampling period is about `2.523`, computed from both-file fitted parameters. This is only a local scalar linear-stability diagnostic for RK4, not a proof of nonlinear integration accuracy. The positive baseline source is empirical and does not establish behavior with both inputs shut off.'))
# Gaussian field with training-estimated centers, affine far-field tail, and shrinkage.
base=scales();base.extend([par('sy',.3,'-','fixed','Additional dimensionless state scaling `sy = 0.3`, chosen from the approximate training state spread for roughly balanced K-means coordinates.'),par('three',3,'-','fixed','Dimensionless input-coordinate scale `three = 3`, chosen so input deviations in `(x1/u0-1)*three` and `(x2/v0-1)*three` have order-one spreads.'),par('ell',G['width'],'-','fitted','Common dimensionless Gaussian width selected with cluster count and ridge penalty by a finite-grid validation-rollout comparison; subsequently carried unchanged into the final weight fit.')])
base_names=['a0','a1','a2','a3'];base_terms=['1','((y-y0)/s0)','(x1/u0)','(x2/v0)']
for n,c,t in zip(base_names,G['coef'][:4],base_terms):base.append(par(n,c,'U_y/s','fitted','Affine-tail coefficient of `'+t+'`; jointly estimated with all bump weights.'))
terms=[n+'*'+t for n,t in zip(base_names,base_terms)]
for i,(center,w) in enumerate(zip(G['centers'],G['coef'][4:])):
 cs=['my'+str(i),'mu'+str(i),'mv'+str(i)];wn='w'+str(i)
 for n,c,coord in zip(cs,center,['((y-y0)/s0)/sy','(x1/u0-1)*three','(x2/v0-1)*three']):base.append(par(n,c,'-','fitted','Center coordinate for `'+coord+'` of Gaussian bump `'+wn+'`, estimated by training-only K-means, then carried unchanged into the final weight fit.'))
 bump='exp(-((((y-y0)/s0)/sy-'+cs[0]+')**2+((x1/u0-1)*three-'+cs[1]+')**2+((x2/v0-1)*three-'+cs[2]+')**2)/(2*ell**2))'
 base.append(par(wn,w,'U_y/s','fitted','Amplitude of local Gaussian bump `'+bump+'`; jointly estimated with all affine-tail coefficients in final regularized rollout fit.'))
 terms.append(wn+'*'+bump)
expr=' + '.join(terms);weightnames=base_names+['w'+str(i) for i in range(len(G['centers']))]
models['gaussian_field']=dict(expressions={'dy':expr},parameters=base,estimation=dict(criterion=criterion+'Added a dimensionless shrinkage penalty `0.01*sum(((coefficient-initial_coefficient)/scale)**2)` where `scale = Max(Abs(initial_coefficient),0.01)` in the optimizer\'s numerical coefficient coordinates. The anchor is the previous training-rollout coefficient vector. The weak penalty limits large compensating local weights where excitation is sparse; it is not a measured noise variance.',data=data+'All centers were estimated on training states and inputs only; validation affects width/count selection and final amplitudes but not center positions.',method='The normalized training coordinates are `((y-y0)/s0)/sy`, `(x1/u0-1)*three`, and `(x2/v0-1)*three`. K-means with `sklearn.cluster.KMeans`, K-means++ initialization, `n_init = 10`, and `random_state = 2026` estimated center coordinates by minimizing within-cluster squared distances; data-dependent K-means++ provides starting centers, so no manually specified numerical centers apply. Gaussian widths `0.7`, `1.2`, and `2`, cluster counts `8`, `16`, `24`, and `40`, and initial ridge penalties `0.0001`, `0.01`, and `1` were screened. For each, initial affine/bump amplitudes minimized training derivative squared error plus ridge penalty with `numpy.linalg.lstsq` on augmented design rows, requiring no starting values. Width `ell = 2`, count `24`, and ridge penalty `0.0001` were selected by lowest validation-rollout RMSE among candidates with negative affine state coefficient. Center coordinates and width were then held unchanged. '+commonmethod+'A first regularized training-rollout coefficient refinement provided the following final-stage start/penalty anchor: '+numeric_starts(weightnames,G['traincoef'],['U_y/s']*len(weightnames))+'. All affine coefficients and Gaussian amplitudes were finally estimated together. The constraint `a1 <= -0.001` U_y/s prevents an unstable affine state tail outside the Gaussian support. The shrinkage weight is `0.01`, a dimensionless solver setting. K-means is reproducible with the stated seed; weight optimization uses no random numbers.',script='reproduce_models.py'),discussion=dict(family='Gaussian radial-basis-function regression with an affine tail, represented as an explicit scalar continuous-time vector field. '+rbfref,interpretation=units+'The affine tail `a0+a1*((y-y0)/s0)+a2*(x1/u0)+a3*(x2/v0)` supplies baseline forcing and negative far-field state feedback. Each `wi` is a signed local change in derivative around the normalized training-input/state center whose coordinates are `myi`, `mui`, and `mvi`; the actual numbered symbols and full bump expressions are specified in the parameter descriptions. `ell` is their common dimensionless width. Positive amplitudes increase the local derivative; negative amplitudes decrease it. No local bump is assigned a physical mechanism.',origin='Polynomial/rational residuals still varied across state-input regions, so localized smooth corrections were tried as a structurally different interpolation family. Training K-means selected centers without fitting derivative labels. Validation rollouts selected width/count/ridge setting. Derivative fits with larger or narrower networks were not consistently better, so the lowest-screening-error configuration was retained rather than maximizing network size. A negative affine tail and mild amplitude shrinkage were imposed to limit unsupported far-field and cancellation behavior.',limitations=limitations+'This model is less parsimonious and less mechanistically interpretable than the recommended polynomial. The center locations are empirical summaries, not physical thresholds; many amplitudes compensate one another. K-means centers may be poorly supported in directions normal to the two trajectories. Far from all centers the field becomes affine, an imposed extrapolation rule rather than a verified law. Its final derivative/trajectory calibration scores do not establish test performance.'))
for label,m in models.items():
 with open('models/'+label+'.json','w') as f:json.dump(m,f,indent=2)
pool=dict(order=['poly3','rational2','cos_power','gaussian_field'],recommended='poly3',reason='Recommend `poly3`: it is a transparent degree-three polynomial field with fewer fitted values than the Gaussian network and the lowest combined-data uninterrupted RK4 state RMSE in this pool. Its final errors are about `0.023325` U_y on `data/train.csv` and `0.033375` U_y on `data/val.csv`; U_y denotes the unspecified state unit. Validation was included in final calibration, so these are not untouched holdout scores. Before final pooling, its training-derivative fit gave validation rollout RMSE about `0.036525` U_y and compared favorably with most compact nonlinear alternatives. The Gaussian model had a slightly lower screened holdout error but higher complexity and no final pooled advantage. The rational and smoothed power-law candidates hedge structural uncertainty, not coefficient uncertainty. No claim is made about unavailable test data.')
json.dump(pool,open('models/pool.json','w'),indent=2)
